        for (int j = 0; j < 7; ++j) put32(f, 2000 + k + j); put32(f, 0xABC0 + k); }
    Cache c; c.NeedsSaving = true; Entry junk; std::memset(&junk, 0, sizeof junk); c.Entries["old"] = junk;
