void NCreatureMode::CModeDragonFireBeam::UpdateBeam()
{
    if (!BeamActive)
        return;
    CDefPointer<const CJackDragonDef> def;
    ParentThing.PeekBaseDef().GetSubDef(&def);
    if (CWorld::GetFrame() - LastExplodeFrame > def->FramesBetweenFireBeamUpdate) {
        C3DVector mouth;
